// Values were generated by the unmodified v9 implementation at commit 685163f.
func TestGenericV8V9FingerprintCompatibility(t *testing.T) {
	at := time.Date(2026, 11, 4, 12, 0, 0, 0, time.UTC)
	commands := []StateCommand{
		{RequestID: "v8-launch", At: at, Job: &JobCommand{Launch: &LaunchJob{TenantID: "tenant", DefinitionID: "work", DefinitionRevision: 1, RunID: "r"}}},
		{RequestID: "v9-put", At: at, Job: &JobCommand{PutTrigger: &PutJobTrigger{Definition: JobTriggerDefinition{TenantID: "tenant", ID: "hourly", DefinitionID: "work", DefinitionRevision: 1, MaxPending: 32, Timing: ScheduleTiming{Spec: ScheduleSpec{Kind: ScheduleInterval, StartAt: at, Interval: time.Hour}, MissedPolicy: MissedCoalesce}}, NextAt: at}}},
		{RequestID: "v9-materialize", At: at, Job: &JobCommand{Materialize: &MaterializeJobs{TenantID: "tenant", Plan: MaterializeRuns{ScheduleID: "hourly", Revision: 1, ExpectedNext: at, Occurrences: []time.Time{at}, NextAt: at.Add(time.Hour)}}}},
	}
	want := map[string]string{
		"v8-launch":      "23c65d6081a6d8514f74bc9b8ccdfcacede05266fa68999bad76b5ba5eac7a27",
		"v9-materialize": "88da88a3d07d9ea86844573f0283594c548867faf64931774870c0e68f732dad",
		"v9-put":         "610073aacf09b1ccdbd9aa7579413aafe7fb041fda01d96c00233f7e5b742639",
	}
	for _, command := range commands {
		hash, err := command.Fingerprint()
		require.NoError(t, err)
		require.Equal(t, want[command.RequestID], fmt.Sprintf("%x", hash), command.RequestID)
	}
}

// Values were generated from the v10 source before tenant quota accounting.
func TestGenericV10FingerprintCompatibility(t *testing.T) {
	at := time.Date(2026, 11, 5, 12, 0, 0, 0, time.UTC)
	trigger := JobCommand{PutTrigger: &PutJobTrigger{Definition: JobTriggerDefinition{TenantID: "tenant", ID: "ingest", DefinitionID: "work", DefinitionRevision: 1, MaxPending: 4, Event: &EventTriggerSpec{Source: "meters"}}}}
	activate := JobCommand{Activate: &ActivateJob{TenantID: "tenant", TriggerID: "ingest", Source: "meters", EventID: "first", OccurredAt: at, Data: []byte{0, 255}}}
	commands := map[string]JobCommand{"v10-trigger": trigger, "v10-activation": activate}
	want := map[string]string{
		"v10-activation": "3bb4faf1100b03554756479d7a5c8ef2caad625ace2b3314f010f666e61d7490",
		"v10-trigger":    "ba71b6b777873723b7119a7d2c5c139703d73e8af2136ac345112693a514380d",
	}
	for id, c := range commands {
		hash, err := (StateCommand{RequestID: id, At: at, Job: &c}).Fingerprint()
		require.NoError(t, err)
		require.Equal(t, want[id], fmt.Sprintf("%x", hash), id)
	}
}

// Generated from the v11 source before adding retention commands.
