	at := time.Date(2026, 11, 5, 12, 0, 0, 0, time.UTC)
	command := StateCommand{RequestID: "v11-limits", At: at, Job: &JobCommand{PutLimits: &PutJobLimits{ExpectedRevision: 2, Limits: JobLimits{TenantID: "tenant", MaxPendingRuns: 2, MaxStoredRuns: 3, MaxInboxEvents: 4, MaxInboxBytes: 5, MaxActivations: 6, MaxActivationBytes: 7}}}}
