// Generated from the v12 source before adding receipt compaction.
func TestGenericV12FingerprintCompatibility(t *testing.T) {
	at := time.Date(2026, 11, 5, 12, 0, 0, 0, time.UTC)
	commands := map[string]JobCommand{
		"v12-policy": {PutRetention: &PutJobRetention{ExpectedRevision: 2, Policy: JobRetentionPolicy{TenantID: "tenant", Enabled: true, KeepFor: 7 * 24 * time.Hour}}},
		"v12-purge":  {Purge: &PurgeJob{TenantID: "tenant", RunID: "run", ExpectedStep: 3, FinishedBefore: at.Add(-time.Hour), BatchSize: 16, Actor: "operator", Reason: "completed history", PolicyRevision: 1}},
	}
	want := map[string]string{
		"v12-policy": "c2dbcbab5c4a5858f6647b345cec11fb7e9d88392b40b8857ff24e4be93ddc81",
		"v12-purge":  "908fbee610835fb74bb5f46c7e5e23c498185ab8116953d9589648b1d6ef1838",
	}
	for id, job := range commands {
		hash, err := (StateCommand{RequestID: id, At: at, Job: &job}).Fingerprint()
		require.NoError(t, err)
		require.Equal(t, want[id], fmt.Sprintf("%x", hash), id)
	}
}

